import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const modulePath=process.argv[2]??'sharp',batch=Number(process.argv[3]??138),partial=process.argv[4]==='partial',sharp=createRequire(import.meta.url)(modulePath),root='art/review/web-v3',folder=root+'/clock-round-calibration-20261026';
await mkdir(folder,{recursive:true});
const prior=JSON.parse(await readFile(root+'/hud-source-calibration-20261026/coverage.json','utf8')),extra=JSON.parse(await readFile('art/source/web-v3/hud-clock-v1/dense-notimer-provenance-v1.json','utf8')),layout=JSON.parse(await readFile('art/runtime/web-v3/hud-clock-v1/clock-layout-v1.json','utf8')),round=JSON.parse(await readFile('art/runtime/web-v3/hud-clock-v1/round-layout-v1.json','utf8'));
const sources=[...prior.reports.map(r=>({profile:r.profile,state:r.state,source:r.source})),...extra.reports.map(r=>({profile:r.profile,state:r.state,source:r.output}))],reports=[],sha=async p=>createHash('sha256').update(await readFile(p)).digest('hex');
const initial=new Set(['idle-landscape','idle-portrait','bid-portrait','dense-idle-portrait','dense-notimer-idle-landscape','dense-notimer-selected-landscape','dense-notimer-idle-portrait','dense-notimer-selected-portrait']);
for(const {profile,state,source}of sources){
 const tall=profile==='portrait',width=tall?390:1672,height=tall?694:941,actualBatch=batch>=139?(initial.has(`${state}-${profile}`)?138:139):batch,prefix=`${actualBatch}-clock-${state}-${profile}-20261026`,record=await readFile(`${root}/${prefix}.json`,'utf8').then(JSON.parse).catch(()=>null);if(!record){if(partial)continue;throw Error('Missing '+prefix);}
 if(record.profile!==profile||record.fonts!=='loaded'||!record.images||!record.furniture?.roundNumber)throw Error('Invalid ready state '+prefix);
 const capture=`${folder}/${state}-${profile}-chrome.png`,out=`${folder}/${state}-${profile}`;
 for(const args of [['tools/stitch-web-chrome-tiles.mjs',`${root}/${prefix}.json`,capture,modulePath],['tools/compare-web-design.mjs',source,capture,out,modulePath,String(width),String(height)]]){const result=spawnSync(process.execPath,args,{encoding:'utf8'});if(result.status)throw Error(result.stderr||result.stdout);}
 await sharp(out+'-comparison.png').jpeg({quality:95,chromaSubsampling:'4:4:4'}).toFile(out+'-comparison.jpg');
 const [cw,ch]=round.profiles[profile].canvas,frame=round.profiles[profile].frame,variant=state.startsWith('dense')?'dense':state.startsWith('bid')?'bid':'normal',tile=layout.profiles[profile][variant].tile;
 const expand=([x,y,w,h],m)=>[Math.max(0,x-m),Math.max(0,y-m),Math.min(cw,x+w+m)-Math.max(0,x-m),Math.min(ch,y+h+m)-Math.max(0,y-m)],boxes=[{kind:'round',rect:expand(frame,4)},{kind:'clock',rect:expand(tile,8)}],inputs=[await sharp(source).resize(width,height,{fit:'fill'}).png().toBuffer(),await readFile(capture)],layers=[];
 for(const [n,box]of boxes.entries()){const [x,y,w,h]=box.rect,region={left:Math.round(x/cw*width),top:Math.round(y/ch*height),width:Math.round(w/cw*width),height:Math.round(h/ch*height)};box.captureRect=region;for(const [i,input]of inputs.entries())layers.push({input:await sharp(input).extract(region).resize(530,250,{fit:'contain',background:'#10151d'}).png().toBuffer(),left:i*538,top:n*258});}
 await sharp({create:{width:1068,height:516,channels:3,background:'#10151d'}}).composite(layers).png().toFile(out+'-focus.png');
 reports.push({profile,state,batch:actualBatch,source,sourceSha256:await sha(source),capture,captureSha256:await sha(capture),comparison:`${state}-${profile}-comparison.jpg`,focus:`${state}-${profile}-focus.png`,focusBoxes:boxes,record,status:'review-required-not-a-pass'});
}
await writeFile(folder+'/coverage.json',JSON.stringify({batch,status:'review-required',scope:'Original round scroll/static Chinese and original timer/hourglass/秒, live numeric fields, dense no-timer removal. Fixture layout evidence is not actual deadline or network proof.',reports},null,2)+'\n');
await writeFile(folder+'/index.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>原稿回合卷轴与计时器</title><style>body{margin:0;padding:24px;background:#10151d;color:#f4e1b5;font:16px/1.6 system-ui}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,650px),1fr));gap:24px}figure{margin:0}img{width:100%;display:block}a{color:inherit}</style><h1>原稿回合卷轴与计时器 · ${reports.length}组</h1><p>左设计右Chrome，当前${batch}。局部上为回合卷轴，下为时钟/无计时区域；遮挡不算隐藏像素验收。静态原字、装饰与实时数值分层，整页仍有P2/缺稿/网络边界。</p><p><a href="coverage.json">来源/实际收据</a> · <a href="../../../../docs/66-web-v3-source-round-and-clocks.md">报告</a></p><main>${reports.map(r=>`<figure><figcaption>${r.state} · ${r.profile}</figcaption><a href="${r.comparison}"><img src="${r.comparison}" alt="左设计右Chrome"></a><a href="${r.focus}">卷轴/时钟局部</a> · <a href="${r.capture.split('/').at(-1)}">Chrome原图</a></figure>`).join('')}</main></html>`);
console.log({folder,count:reports.length});
